using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

// Configure the AI client with tool support
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var researchNotes = new ResearchNotes();
var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch.SearchAsync),
        AIFunctionFactory.Create(researchNotes.AddNote),
        AIFunctionFactory.Create(researchNotes.GetNotes),
    ]
};

// Get the research topic
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.

        Follow these steps:
        1. Search the web for information about the topic (perform 2-3 searches with different queries).
        2. Take notes on the key findings from each search using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and produce a final summary.

        Always use the tools available to you. Be thorough but concise in your final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, tools);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchNotes.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"{i + 1}. [{notes[i].Source}] {notes[i].Content}");
    }
}

// --- Tool Definitions ---

/// <summary>Simulates web search functionality.</summary>
public static class WebSearch
{
    [Description("Search the web for information on a given query. Returns a list of search results with titles, snippets, and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        // In production, replace with a real search API (e.g., Bing Search API)
        await Task.Delay(100); // Simulate network latency

        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        var results = new[]
        {
            new { Title = $"Overview of {query}", Snippet = $"A comprehensive overview covering the main aspects of {query}, including history, current state, and future outlook.", Url = $"https://example.com/overview-{Uri.EscapeDataString(query)}" },
            new { Title = $"Latest developments in {query}", Snippet = $"Recent breakthroughs and developments related to {query} that are shaping the field in 2026.", Url = $"https://example.com/latest-{Uri.EscapeDataString(query)}" },
            new { Title = $"{query} - Expert Analysis", Snippet = $"Expert analysis and opinions on {query}, covering benefits, challenges, and practical applications.", Url = $"https://example.com/analysis-{Uri.EscapeDataString(query)}" },
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

/// <summary>Note-taking tool for the research agent.</summary>
public class ResearchNotes
{
    private readonly List<Note> _notes = [];

    [Description("Add a research note with content and its source. Use this to record key findings during research.")]
    public string AddNote(
        [Description("The content of the note")] string content,
        [Description("The source URL or description where this information came from")] string source)
    {
        _notes.Add(new Note(content, source));
        Console.WriteLine($"  📝 Note added: {content[..Math.Min(content.Length, 60)]}...");
        return $"Note added successfully. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    public List<Note> GetAllNotes() => [.. _notes];
}

public record Note(string Content, string Source);

